"""Regenerate Java regex case mappings from Unicode 16.0 UnicodeData.txt."""

import hashlib
from pathlib import Path
import sys


EXPECTED_SHA256 = "ff58e5823bd095166564a006e47d111130813dcf8bf234ef79fa51a870edb48f"
HEADER = """// Generated by generate_java_case.py from Unicode 16.0 UnicodeData.txt.
// See ../LICENSE-UNICODE for the Unicode data license.

pub(super) fn fold(character: char) -> u32 {
    map(u32::from(character), FOLD_RANGES)
}

pub(super) fn map(code: u32, ranges: &[CaseRange]) -> u32 {
    let index = ranges.partition_point(|&(_, last, _, _)| last < code);
    if let Some(&(first, _, stride, delta)) = ranges.get(index) {
        if code >= first && (code - first) % stride == 0 {
            return code.wrapping_add_signed(delta);
        }
    }
    code
}

// Inclusive start and end, stride, and signed mapping offset.
pub(super) type CaseRange = (u32, u32, u32, i32);
"""


def case_ranges(mappings):
    index = 0
    while index < len(mappings):
        first, target = mappings[index]
        delta = target - first
        last = first
        index += 1
        stride = mappings[index][0] - first if index < len(mappings) else 1
        if stride in (1, 2):
            while index < len(mappings):
                code, target = mappings[index]
                if code - last != stride or target - code != delta:
                    break
                last = code
                index += 1
        yield first, last, stride if last > first else 1, delta


def rust_table(name, mappings):
    rows = "".join(
        f"    (0x{first:X}, 0x{last:X}, {stride}, {delta}),\n"
        for first, last, stride, delta in case_ranges(mappings)
    )
    return f"\npub(super) const {name}: &[CaseRange] = &[\n{rows}];\n"


def main():
    if len(sys.argv) != 2:
        raise SystemExit("Usage: generate_java_case.py UnicodeData.txt")
    data = Path(sys.argv[1]).read_bytes()
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        raise SystemExit("The input is not the expected Unicode 16.0 UnicodeData.txt.")
    upper = {}
    lower = {}
    for record in data.decode("utf-8").splitlines():
        fields = record.split(";")
        code = int(fields[0], 16)
        if fields[12]:
            upper[code] = int(fields[12], 16)
        if fields[13]:
            lower[code] = int(fields[13], 16)

    # Java compares the simple uppercase forms and then their simple lowercase
    # forms. Equal uppercase forms already imply equal lowercase forms.
    mappings = []
    for code in sorted(upper.keys() | lower.keys()):
        uppercase = upper.get(code, code)
        folded = lower.get(uppercase, uppercase)
        if folded != code:
            if (code <= 0xFFFF) != (folded <= 0xFFFF):
                raise ValueError("A case mapping changed the UTF-16 width.")
            mappings.append((code, folded))

    output = Path(__file__).with_name("src") / "java_case.rs"
    output.write_text(
        HEADER + rust_table("FOLD_RANGES", mappings) + rust_table("UPPER_RANGES", sorted(upper.items())),
        encoding="utf-8",
        newline="\n",
    )


if __name__ == "__main__":
    main()
